// Open settings and let its layout render. Exercises native Slider/Toggle event handlers.
if(!UnityEditor.EditorApplication.isPlaying)throw new System.Exception("Run in Play.");
GameObject Named(string n)=>UnityEngine.Object.FindObjectsByType<Transform>(UnityEngine.FindObjectsInactive.Include,UnityEngine.FindObjectsSortMode.None).Single(t=>t.name==n).gameObject;
int checks=0;void Check(bool ok,string label){if(!ok)throw new System.Exception("FAIL: "+label);checks++;}
if(!UnityEngine.Object.FindFirstObjectByType<SettingsPanelController>().IsOpen)throw new System.Exception("Open settings.");
foreach(var item in new[]{new{name="MusicVolumeSlider",value=.75f},new{name="EffectsVolumeSlider",value=.35f}}){var slider=Named(item.name).GetComponent<UnityEngine.UI.Slider>();var area=slider.handleRect.parent as RectTransform;var point=area.TransformPoint(new Vector3(area.rect.xMin+area.rect.width*item.value,area.rect.center.y));var data=new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current){button=UnityEngine.EventSystems.PointerEventData.InputButton.Left,position=RectTransformUtility.WorldToScreenPoint(null,point)};slider.OnPointerDown(data);slider.OnDrag(data);slider.OnPointerUp(data);Check(Mathf.Abs(slider.value-item.value)<.001f,item.name+" accepts pointer dragging");Check(Mathf.Abs(slider.handleRect.anchorMin.x-slider.value)<.001f&&Mathf.Abs(slider.fillRect.anchorMax.x-slider.value)<.001f,item.name+" thumb and fill match its value");}
foreach(string name in new[]{"MuteAudioToggle","ReducedMotionToggle"}){var toggle=Named(name).GetComponent<UnityEngine.UI.Toggle>();bool previous=toggle.isOn;toggle.OnPointerClick(new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current){button=UnityEngine.EventSystems.PointerEventData.InputButton.Left});Check(toggle.isOn!=previous,name+" accepts pointer click");toggle.OnPointerClick(new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current){button=UnityEngine.EventSystems.PointerEventData.InputButton.Left});Check(toggle.isOn==previous,name+" restores its previous value");}
Named("MusicVolumeSlider").GetComponent<UnityEngine.UI.Slider>().value=.25f;Named("EffectsVolumeSlider").GetComponent<UnityEngine.UI.Slider>().value=.6f;
return new{passed=checks};
